<?php $remaining=(int)q('SELECT COUNT(*) FROM recovery_codes WHERE user_id=? AND used_at IS NULL',[user()['id']])->fetchColumn(); $totalCodes=(int)q('SELECT COUNT(*) FROM recovery_codes WHERE user_id=?',[user()['id']])->fetchColumn(); ?>
<section class="panel profile-panel section-space"><h2>Password recovery codes</h2><p class="muted small">Save these codes somewhere private. Each code can reset your password once. <?php if($remaining):?><?=$remaining?> unused codes remain.<?php elseif(!$totalCodes):?>No recovery codes generated yet (0 unused codes remain).<?php else:?>No unused recovery codes remain. Generate a new set.<?php endif;?> Generating a new set invalidates the old set.</p>
<?php if(!empty($_SESSION['new_recovery_codes'])):$codes=$_SESSION['new_recovery_codes'];unset($_SESSION['new_recovery_codes']);?><div class="recovery-codes"><p><strong>Save these codes now. They are shown only once.</strong></p><pre id="recovery-code-text"><?=e(implode("\n",$codes))?></pre><button type="button" class="button secondary" id="download-recovery">Download codes</button></div><?php endif;?>
<form method="post" data-confirm="Generate a new set? All previous recovery codes will stop working."><?php csrf();?><input type="hidden" name="action" value="generate_recovery"><label>Current password<input type="password" name="current_password" autocomplete="current-password" required></label><button class="button secondary">Generate recovery codes</button></form></section>
